12	#brand{position:fixed;top:12px;left:16px;font-size:15px;font-weight:650;letter-spacing:.02em;color:#fff;text-shadow:0 1px 8px rgba(0,0,0,.55);pointer-events:none;z-index:5}
13	#bar{position:fixed;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:12px;background:rgba(14,18,25,.72);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.12);box-shadow:0 8px 30px rgba(0,0,0,.4);z-index:6;max-width:calc(100vw - 16px);flex-wrap:wrap;justify-content:center}
14	.grp{display:flex;gap:2px;padding:2px;border-radius:8px;background:rgba(255,255,255,.06)}
15	button{font:inherit;color:#dfe6ee;background:transparent;border:0;border-radius:6px;padding:6px 10px;cursor:pointer;white-space:nowrap}
16	button:hover{background:rgba(255,255,255,.12)}
17	button.on{background:#e8edf3;color:#0d1117;font-weight:650}
18	button.act{background:#2f6fed;color:#fff;font-weight:650}
19	button.act:hover{background:#4a83f5}
20	#hud{min-width:150px;color:#9fb0c3;font-variant-numeric:tabular-nums;font-size:11px}
21	#panel{position:fixed;top:0;right:0;bottom:0;width:292px;padding:14px 14px 76px;overflow:auto;background:rgba(14,18,25,.86);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-left:1px solid rgba(255,255,255,.12);transform:translateX(102%);transition:transform .22s ease;z-index:7}
22	#panel.open{transform:none}
23	#panel h3{margin:14px 0 6px;font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:#7f93a9;font-weight:650}
24	#panel h3:first-child{margin-top:0}
25	.row{display:grid;grid-template-columns:1fr 92px;align-items:center;gap:8px;margin:4px 0}
