28	input[type=number]{width:100%;font:inherit;color:#fff;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:6px;padding:5px 6px;text-align:right;font-variant-numeric:tabular-nums}
29	input[type=number]:focus{outline:2px solid #2f6fed;outline-offset:0}
30	.pbtns{display:flex;gap:8px;margin-top:16px}
31	.pbtns button{flex:1;padding:8px 10px;border:1px solid rgba(255,255,255,.16)}
32	#err{position:fixed;inset:auto 16px 70px 16px;color:#ffb4b4;z-index:9;display:none}
33	</style>
