61	const DEFAULTS = { speed: 22, carMass: 1250, carL: 4.2, carW: 1.8, carH: 1.45, cols: 12, rows: 8, depth: 2,
62	  brickMass: 2.5, bw: 0.5, bh: 0.24, bd: 0.2, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18,
63	  groundFriction: 0.85, trackLen: 40 };
64	const SCHEMA = [
65	  ['Impact', [['speed', 'Impact speed', 'm/s', 3, 60, 0.5], ['carMass', 'Car mass', 'kg', 300, 6000, 10]]],
66	  ['Car body', [['carL', 'Length', 'm', 3.2, 6, 0.05], ['carW', 'Width', 'm', 1.4, 2.4, 0.05], ['carH', 'Height', 'm', 1.1, 2.2, 0.05]]],
67	  ['Wall', [['cols', 'Columns', '', 3, 24, 1], ['rows', 'Rows', '', 1, 16, 1], ['depth', 'Depth (bricks)', '', 1, 4, 1]]],
68	  ['Bricks', [['brickMass', 'Mass', 'kg', 0.3, 80, 0.1], ['bw', 'Width', 'm', 0.2, 1, 0.01], ['bh', 'Height', 'm', 0.1, 0.5, 0.01], ['bd', 'Depth', 'm', 0.1, 0.5, 0.01]]],
