80	/* ---------- procedural textures (seeded, no external files) ---------- */
81	function canvasTex(w, h, draw, rep, srgb = true) {
82	  const c = document.createElement('canvas'); c.width = w; c.height = h;
83	  draw(c.getContext('2d'), w, h);
84	  const t = new THREE.CanvasTexture(c);
85	  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
86	  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8;
87	  if (rep) t.repeat.set(rep[0], rep[1]);
88	  return t;
89	}
90	function speckle(g, w, h, base, n, rng, size = 1.6, spread = 0.5) {
91	  g.fillStyle = base; g.fillRect(0, 0, w, h);
92	  for (let i = 0; i < n; i++) {
93	    const d = rng() < 0.5;
94	    g.fillStyle = d ? `rgba(0,0,0,${(rng() * spread).toFixed(3)})` : `rgba(255,255,255,${(rng() * spread * 0.7).toFixed(3)})`;
95	    const s = 0.6 + rng() * size; g.fillRect(rng() * w, rng() * h, s, s);
96	  }
97	}
98	const TEX = {};
99	function makeTextures() {
100	  const r = mulberry32(VIS_SEED);
101	  TEX.asphalt = canvasTex(512, 512, (g, w, h) => {
102	    speckle(g, w, h, '#3a3c41', 60000, r, 2.2, 0.55);
103	    g.strokeStyle = 'rgba(0,0,0,.35)'; g.lineWidth = 1.2;
104	    for (let i = 0; i < 9; i++) { g.beginPath(); let x = r() * w, y = r() * h; g.moveTo(x, y); for (let k = 0; k < 6; k++) { x += (r() - .5) * 60; y += (r() - .5) * 60; g.lineTo(x, y); } g.stroke(); }
105	  });
106	  TEX.grass = canvasTex(512, 512, (g, w, h) => {
107	    speckle(g, w, h, '#4c7a38', 70000, r, 2.6, 0.5);
108	    for (let i = 0; i < 9000; i++) { g.fillStyle = `hsla(${85 + r() * 40},50%,${25 + r() * 25}%,.5)`; g.fillRect(r() * w, r() * h, 1.2, 3.2); }
109	  });
110	  TEX.gravel = canvasTex(512, 512, (g, w, h) => {
111	    speckle(g, w, h, '#8b877f', 20000, r, 1, 0.5);
112	    for (let i = 0; i < 16000; i++) { const v = 90 + r() * 110 | 0; g.fillStyle = `rgb(${v},${v - 4},${v - 10})`; g.beginPath(); g.arc(r() * w, r() * h, 0.7 + r() * 2.1, 0, 7); g.fill(); }
113	  });
114	  TEX.brick = canvasTex(128, 64, (g, w, h) => {
115	    g.fillStyle = '#cfc7b8'; g.fillRect(0, 0, w, h);
116	    g.fillStyle = '#b1503a'; g.fillRect(3, 3, w - 6, h - 6);
117	    for (let i = 0; i < 1400; i++) { g.fillStyle = r() < .5 ? `rgba(60,20,10,${(r() * .35).toFixed(2)})` : `rgba(255,190,150,${(r() * .22).toFixed(2)})`; g.fillRect(3 + r() * (w - 6), 3 + r() * (h - 6), 1 + r() * 2.5, 1 + r() * 1.6); }
118	  });
119	  TEX.start = canvasTex(128, 512, (g, w, h) => {
120	    const rows = 14, cw = w / 2, ch = h / rows;
121	    for (let y = 0; y < rows; y++) for (let x = 0; x < 2; x++) { g.fillStyle = (x + y) % 2 ? '#111' : '#f2f2f2'; g.fillRect(x * cw, y * ch, cw, ch + 1); }
122	  });
123	  TEX.start.wrapS = TEX.start.wrapT = THREE.ClampToEdgeWrapping;
124	  TEX.blob = canvasTex(128, 128, (g, w, h) => {
125	    const gr = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
126	    gr.addColorStop(0, '#fff'); gr.addColorStop(0.45, '#9a9a9a'); gr.addColorStop(1, '#000');
127	    g.fillStyle = gr; g.fillRect(0, 0, w, h);
128	  }, null, false);
129	  TEX.blob.wrapS = TEX.blob.wrapT = THREE.ClampToEdgeWrapping;
130	}
131	
132	/* ---------- renderer / scene / lighting ---------- */
133	const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
134	renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
135	renderer.outputColorSpace = THREE.SRGBColorSpace;
136	renderer.toneMapping = THREE.ACESFilmicToneMapping;
137	renderer.toneMappingExposure = 1.02;
