63	  brickMass: 2.5, bw: 0.5, bh: 0.24, bd: 0.2, gravity: 9.81, brickFriction: 0.72, brickRestitution: 0.18,
64	  groundFriction: 0.85, trackLen: 40 };
65	const SCHEMA = [
66	  [['speed', 'Impact speed', 'm/s', 3, 60, 0.5], ['carMass', 'Car mass', 'kg', 300, 6000, 10]],
67	  [['carL', 'Car length', 'm', 3.6, 6, 0.05], ['carW', 'Car width', 'm', 1.4, 2.4, 0.05], ['carH', 'Car height', 'm', 1.1, 2.2, 0.05]],
68	  [['cols', 'Wall columns', '', 3, 24, 1], ['rows', 'Wall rows', '', 1, 16, 1], ['depth', 'Wall depth (bricks)', '', 1, 4, 1]],
69	  [['brickMass', 'Brick mass', 'kg', 0.3, 80, 0.1], ['bw', 'Brick width', 'm', 0.2, 1, 0.01], ['bh', 'Brick height', 'm', 0.1, 0.5, 0.01], ['bd', 'Brick depth', 'm', 0.1, 0.5, 0.01]],
70	  [['gravity', 'Gravity', 'm/s²', 1, 25, 0.01], ['brickFriction', 'Brick friction', '', 0, 1.5, 0.01],
