81	/* ---------- procedural textures (seeded, no external files) ---------- */
82	function canvasTex(w, h, draw, rep, srgb = true) {
83	  const c = document.createElement('canvas'); c.width = w; c.height = h;
84	  draw(c.getContext('2d'), w, h);
85	  const t = new THREE.CanvasTexture(c);
86	  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
87	  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8;
88	  if (rep) t.repeat.set(rep[0], rep[1]);
89	  return t;
90	}
91	function speckle(g, w, h, base, n, rng, size = 1.6, spread = 0.5) {
92	  g.fillStyle = base; g.fillRect(0, 0, w, h);
93	  for (let i = 0; i < n; i++) {
94	    const d = rng() < 0.5;
95	    g.fillStyle = d ? `rgba(0,0,0,${(rng() * spread).toFixed(3)})` : `rgba(255,255,255,${(rng() * spread * 0.7).toFixed(3)})`;
96	    const s = 0.6 + rng() * size; g.fillRect(rng() * w, rng() * h, s, s);
97	  }
98	}
