379	  p.geo = (geo, mat, cast = true) => put(new THREE.Mesh(geo, mat), cast).position.set(-p.pos.x, -p.pos.y, -p.pos.z);
380	  p.rod = (a, b, th, mat) => {
381	    const A = new THREE.Vector3(...a), Bv = new THREE.Vector3(...b), d = Bv.clone().sub(A), len = d.length();
382	    const m = put(new THREE.Mesh(new THREE.BoxGeometry(th, len, th), mat));
383	    m.position.copy(A.add(Bv).multiplyScalar(0.5)).sub(p.pos); m.quaternion.setFromUnitVectors(Y_UP, d.normalize()); return m;
384	  };
385	  run.parts.push(p); run.byId[id] = p; return p;
386	}
