388	function addLink(run, child, parent, o) {
389	  const l = { child, parent, stage: 0, joint: null, yG: 1e9, bG: 1e9, next: null, ...o };
390	  child.parent = parent; child.link = l; parent.kids.push(child); run.links.push(l); return l;
391	}
392	function weldData(a, b, P) {
393	  const ia = a.q.clone().invert(), ib = b.q.clone().invert();
394	  const la = P.clone().sub(a.pos).applyQuaternion(ia), lb = P.clone().sub(b.pos).applyQuaternion(ib);
395	  return RAPIER.JointData.fixed(vv(la), qq(ia), vv(lb), qq(ib));
396	}
