/* ---------- the car: rigid parts, breakable links, glass panes ---------- */
const hash01 = n => { n = Math.imul(n ^ (n >>> 16), 0x45d9f3b); n = Math.imul(n ^ (n >>> 16), 0x45d9f3b); return ((n ^ (n >>> 16)) >>> 0) / 4294967296; };
const V3 = (x, y, z) => new THREE.Vector3(x, y, z);
const _e = new THREE.Euler(), _q2 = new THREE.Quaternion();
function quad3(a, b, c, d) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([...a, ...b, ...c, ...d], 3));
  g.setIndex([0, 1, 2, 0, 2, 3]); g.computeVertexNormals(); return g;
}

function buildCar(run) {
  const S = run.S, L = S.carL, W = S.carW, H = S.carH, world = run.world, cx = run.startX;
  const kn = 1000 * Math.sqrt(S.carMass / 1250);
  const wr = Math.min(0.235 * H, 0.08 * L), ww = clamp(0.135 * W, 0.2, 0.32);
  const yb = wr * 0.7, ht = 0.06, yh = 0.62 * H, yt = yh - ht, ym = (yb + yt) / 2;
  const bw2 = W / 2 - ww - 0.06, zW = W / 2 - ww / 2 - 0.02, hw = W / 2 - 0.1, archR = wr + 0.035;
  const X = f => cx + f * L, AX = 0.31, C0 = 0.12, C1 = 0.435;
  run.wr = wr; run.hits = []; run.peakF = 0; run.stepN = 0; run.glass = []; run.carPos = new THREE.Vector3(cx, 0.7, 0);

  const addGlass = (owner, geo, pts, gLim, fLim) => {
    const mesh = owner.geo(geo, M.glass, false); owner.gOwn = true;
    run.glass.push({ owner, mesh, loc: pts.map(q => q.clone().sub(owner.pos)), nx: 6, ny: 4, gLim: gLim * 9.81, fLim: fLim * kn, done: false, seed: run.glass.length * 97 + 11 });
  };
  const sideGlass = (owner, s, q2) => { const z = s * (W / 2 - 0.06); addGlass(owner, quadGeo(q2).translate(0, 0, z), q2.map(([x, y]) => V3(x, y, z)), 22, 30); };

  // front clip (engine bay + fenders)
  const fx = X((C0 + C1) / 2), front = newPart(run, 'front', [fx, ym, 0], 0.30, true);
  front.box(fx, ym, 0, (C1 - C0) * L, yt - yb, 2 * bw2, M.dark);
  front.col(fx, yt - 0.04, 0, (C1 - C0) * L, 0.08, W - 0.04);
  for (const s of [-1, 1]) front.geo(extrudeShape(fenderShape(X(C0), X(C1), yb, yh, X(AX), archR, wr), 0.1, s * (W / 2 - 0.05)), M.paint);
  front.box(X(C1) - 0.02, ym + 0.05, 0, 0.05, 0.28, W * 0.5, M.trim, false);
  front.blob = [(C1 - C0) * L * 1.05, W * 0.95];

  // cabin (passenger cell + rear deck)
  const cabX = X((-0.44 + C0) / 2), cabW = (C0 + 0.44) * L, cab = newPart(run, 'cabin', [cabX, ym, 0], 0.28, true);
  cab.box(cabX, ym, 0, cabW, yt - yb, 2 * bw2, M.dark);
  cab.box(X(-0.095), H - 0.03, 0, 0.28 * L, 0.06, W - 0.44, M.paint);
  cab.box(X(-0.10), (yt + H - 0.06) / 2, 0, 0.24 * L, H - 0.06 - yt, 0.12, M.interior);
  cab.box(X(0.005), yt + 0.28, -0.38, 0.1, 0.5, 0.42, M.seat, false); cab.box(X(0.005), yt + 0.28, 0.38, 0.1, 0.5, 0.42, M.seat, false);
  cab.box(X(-0.17), yt + 0.25, 0, 0.1, 0.45, W * 0.62, M.seat, false);
  cab.box(X(0.09), yt + 0.1, 0, 0.06 * L, 0.2, W - 0.5, M.interior, false);
  cab.box(X(-0.44) + 0.02, yt - 0.1, -(W / 2 - 0.3), 0.04, 0.14, 0.3, M.tail, false); cab.box(X(-0.44) + 0.02, yt - 0.1, W / 2 - 0.3, 0.04, 0.14, 0.3, M.tail, false);
  for (const s of [-1, 1]) {
    cab.geo(extrudeShape(fenderShape(X(-0.44), X(-0.22), yb, yh, X(-AX), archR, wr), 0.1, s * (W / 2 - 0.05)), M.paint);
    cab.rod([X(C0), yh, s * (W / 2 - 0.14)], [X(0.045), H - 0.03, s * (W / 2 - 0.22)], 0.07, M.paintDark);
    cab.rod([X(-0.235), H - 0.03, s * (W / 2 - 0.22)], [X(-0.31), yh, s * (W / 2 - 0.2)], 0.07, M.paintDark);
    cab.rod([X(-0.013), yh, s * (W / 2 - 0.07)], [X(-0.013), H - 0.05, s * (W / 2 - 0.16)], 0.06, M.paintDark);
    cab.rod([X(0.045), H - 0.03, s * (W / 2 - 0.22)], [X(-0.235), H - 0.03, s * (W / 2 - 0.22)], 0.06, M.paintDark);
    const zc = (bw2 + W / 2 - 0.07) / 2; cab.box(X(-0.01), ym, s * zc, 0.42 * L, yt - yb, W / 2 - 0.07 - bw2, M.interior, false);
  }
  const wsB = W / 2 - 0.14, wsT = W / 2 - 0.26, rwB = W / 2 - 0.2, rwT = W / 2 - 0.3;
  const ws = [[X(C0), yh, -wsB], [X(C0), yh, wsB], [X(0.045), H - 0.07, wsT], [X(0.045), H - 0.07, -wsT]];
  addGlass(cab, quad3(...ws), ws.map(p => V3(...p)), 15, 40);
  const rw = [[X(-0.31), yh, -rwB], [X(-0.31), yh, rwB], [X(-0.235), H - 0.07, rwT], [X(-0.235), H - 0.07, -rwT]];
  addGlass(cab, quad3(...rw), rw.map(p => V3(...p)), 20, 40);
  cab.blob = [cabW, W * 0.95];

  // bumpers
  const mkBumper = (id, sgn) => {
    const bx = X(0.47 * sgn), b = newPart(run, id, [bx, 0.41, 0], 0.03, true);
